code.snippet:
/* display-only: two rules, one winner */
.title { color: blue; }
#page-title { color: red; } /* this one wins */

p {
  color: red !important; /* the nuclear option */
}

body {
  color: #333;         /* inherited everywhere */
  font-family: Arial;  /* inherited everywhere */
}
.card {
  color: inherit; /* explicitly take parent's */
}

/* display-only: keep selectors flat */
.card .title { color: navy; }      /* good: score 20 */
#app #main .card .title { color: navy; } /* overkill */
